
INSERT INTO resources (slug, resource_type, title, description, long_description, category, compatible_platforms, is_free, is_featured, prompt_content, source_url, author, tags) VALUES

('owui-skill-summarization', 'skill', 'Text Summarization Skill', 'Summarizes any text at multiple depth levels — one-line, short, detailed, bullets, or structured JSON.',
'A reusable Open WebUI skill for text summarization at five depth levels. Extracts key points, identifies the main argument, notes caveats, and outputs in multiple formats including structured JSON. Compatible with any LLM backend.',
'content-marketing', ARRAY['Open WebUI', 'LobeHub', 'Hermes Agent'], true, true,
E'## Text Summarization Skill\n\n### Install in Open WebUI\nAdmin Panel → Skills → Import Skill → Paste this skill definition\n\n### Skill Code\n```python\n"""\nskill: text-summarization\nversion: 1.2.0\ndescription: Multi-level text summarization with key point extraction\nauthor: Open WebUI Community\n"""\n\ndef summarize(text: str, format: str = "SHORT") -> str:\n    """\n    Summarize the provided text.\n    :param text: The text to summarize\n    :param format: ONE_LINE | SHORT | DETAILED | BULLETS | STRUCTURED\n    :return: Summary in requested format\n    """\n    formats = {\n        "ONE_LINE": "A single sentence (max 25 words) capturing the core message.",\n        "SHORT": "A paragraph (3-5 sentences) covering the main points.",\n        "DETAILED": "Main Argument + Key Points (5-7 bullets) + Important Details + Caveats + Takeaway.",\n        "BULLETS": "All key information as a flat prioritized bulleted list.",\n        "STRUCTURED": "JSON: {headline, summary, key_points[], entities[], sentiment, word_count_original}"\n    }\n    instruction = formats.get(format.upper(), formats["SHORT"])\n    return f"Summarize the following text. Format: {instruction}\\n\\nText:\\n{text}"\n```\n\n### Usage Examples\n- Quick summary: `summarize(article, "ONE_LINE")`\n- Full analysis: `summarize(paper, "DETAILED")`\n- Pipeline output: `summarize(doc, "STRUCTURED")`\n\n### Tips\n- Chain: chunk long docs → summarize each → summarize summaries\n- Use STRUCTURED for downstream processing pipelines',
'https://openwebui.com/functions', 'Open WebUI Community', ARRAY['summarization', 'nlp', 'documents', 'key-points', 'extraction']),

('owui-skill-sentiment-analysis', 'skill', 'Sentiment Analysis Skill', 'Classifies text sentiment with fine-grained labels, confidence scores and aspect-level breakdowns.',
'Classification skill for sentiment at multiple granularities: overall sentiment, emotion categories, aspect-level sentiment, and confidence scores. Returns structured JSON for downstream processing.',
'research-analysis', ARRAY['Open WebUI', 'LobeHub', 'SwarmClaw'], true, false,
E'## Sentiment Analysis Skill\n\n```python\n"""\nskill: sentiment-analysis\nversion: 1.0.0\n"""\n\ndef analyze_sentiment(text: str) -> str:\n    """\n    Analyze the sentiment and emotions in the provided text.\n    :param text: Text to analyze\n    :return: JSON sentiment analysis\n    """\n    return """Analyze the sentiment of this text and return ONLY valid JSON.\n\nText: """ + text + """\n\nRequired JSON schema:\n{\n  "overall_sentiment": "positive|negative|neutral|mixed",\n  "confidence": 0.0,\n  "valence_score": 0.0,\n  "emotions": {"joy":0.0,"trust":0.0,"fear":0.0,"surprise":0.0,"sadness":0.0,"disgust":0.0,"anger":0.0,"anticipation":0.0},\n  "dominant_emotion": "string",\n  "aspects": [{"aspect":"string","sentiment":"string","confidence":0.0,"evidence":"string"}],\n  "summary": "string",\n  "flags": []\n}"""\n```\n\n### Batch Aggregation\n```python\ndef aggregate_sentiment(results: list) -> dict:\n    pos = sum(1 for r in results if r["overall_sentiment"] == "positive")\n    neg = sum(1 for r in results if r["overall_sentiment"] == "negative")\n    avg = sum(r["valence_score"] for r in results) / len(results)\n    return {"positive_pct": pos/len(results), "negative_pct": neg/len(results), "avg_valence": avg}\n```',
'https://openwebui.com/functions', 'Open WebUI Community', ARRAY['sentiment', 'classification', 'nlp', 'emotions', 'analysis']),

('hermes-skill-translator', 'skill', 'Universal Translator Skill', 'Translates text between 100+ languages with tone preservation, idiom handling and back-translation verification.',
'Professional translation skill that adapts idioms and cultural references naturally, maintains tone and register, and provides back-translation for verification. Supports 100+ languages.',
'content-marketing', ARRAY['Hermes Agent', 'Open WebUI', 'LobeHub'], true, false,
E'## Universal Translator Skill\n\n```python\n"""\nskill: universal-translator\nversion: 2.0.0\n"""\n\ndef translate(text: str, target_lang: str, source_lang: str = "auto", tone: str = "preserve") -> str:\n    """\n    Translate text to the target language.\n    :param text: Text to translate\n    :param target_lang: e.g. "Spanish", "zh-CN", "Japanese"\n    :param source_lang: Source language or "auto"\n    :param tone: preserve | formal | informal | technical\n    :return: Translation with adaptation notes\n    """\n    return (\n        f"Translate to {target_lang} (source: {source_lang}, tone: {tone}).\\n\\n"\n        "Rules:\\n"\n        "1. Preserve exact meaning and intent\\n"\n        "2. Adapt idioms naturally (never literal idiom translation)\\n"\n        "3. Maintain same register/formality as original\\n"\n        "4. Keep all code blocks and HTML untranslated\\n"\n        "5. Add notes for ambiguous phrases\\n\\n"\n        "Format:\\n---TRANSLATION---\\n[translated text]\\n\\n"\n        "---NOTES--- (only if needed)\\n"\n        "- original phrase adapted as translation (reason)\\n\\n"\n        f"Text:\\n{text}"\n    )\n```\n\n### Supported Languages\nEnglish, Spanish, French, German, Italian, Portuguese, Dutch, Russian,\nChinese (Simplified/Traditional), Japanese, Korean, Arabic, Hindi,\nTurkish, Polish, Swedish, Thai, Vietnamese, Indonesian, +80 more',
'https://hermesagent.ai/skills', 'Hermes Agent', ARRAY['translation', 'languages', 'localization', 'multilingual', 'i18n']),

('lobehub-skill-image-analyzer', 'skill', 'Image Analysis Skill', 'Analyzes images for content, objects, text (OCR), sentiment, accessibility issues and structured data extraction.',
'Multimodal skill for deep image analysis: object detection, OCR text extraction, structured data extraction from charts/forms/tables, accessibility auditing, and aesthetic/mood analysis.',
'research-analysis', ARRAY['LobeHub', 'Open WebUI', 'Claude'], true, true,
E'## Image Analysis Skill\n\n```python\n"""\nskill: image-analyzer\nversion: 1.3.0\n"""\n\ndef analyze_image(image_url: str, mode: str = "FULL") -> str:\n    """\n    Analyze an image.\n    :param image_url: URL or base64 data URI of the image\n    :param mode: FULL | OCR | DATA_EXTRACT | ACCESSIBILITY | SENTIMENT\n    :return: Analysis result\n    """\n    prompts = {\n        "FULL": (\n            "Analyze this image comprehensively:\\n"\n            "1. Scene Description\\n2. Objects with locations\\n"\n            "3. All visible text (transcribe exactly)\\n"\n            "4. People (describe, never identify)\\n"\n            "5. Mood and atmosphere\\n6. Technical quality\\n"\n            "7. Any structured data (tables/charts/forms)\\n"\n            "Return structured JSON."\n        ),\n        "OCR": "Extract ALL text from this image exactly as written. Preserve layout. Return plain text.",\n        "DATA_EXTRACT": (\n            "Extract all structured data:\\n"\n            "TABLE -> JSON array of objects\\n"\n            "CHART -> {chart_type, title, data_points, labels, values}\\n"\n            "FORM -> {field_name: filled_value}\\n"\n            "RECEIPT -> {vendor, date, items, total, tax}\\n"\n            "Return ONLY JSON."\n        ),\n        "ACCESSIBILITY": (\n            "Audit for accessibility:\\n"\n            "1. Suggested alt text (max 125 chars)\\n"\n            "2. Long description for complex images\\n"\n            "3. Text readability assessment\\n"\n            "4. Color-only information check (WCAG fail)\\n"\n            "Return JSON."\n        ),\n    }\n    return prompts.get(mode.upper(), prompts["FULL"])\n```',
'https://lobehub.com/plugins', 'LobeHub', ARRAY['image-analysis', 'ocr', 'multimodal', 'vision', 'extraction']),

('swarmclaw-skill-task-decomposer', 'skill', 'Task Decomposer Skill', 'Breaks complex goals into structured parallelizable subtasks with dependencies, effort estimates and acceptance criteria.',
'Takes any complex goal and breaks it into a directed acyclic graph of actionable subtasks. Identifies sequential dependencies vs parallel opportunities, estimates effort, assigns agent types, defines acceptance criteria, and outputs a machine-readable JSON task plan.',
'productivity', ARRAY['SwarmClaw', 'Agency Agents', 'Open WebUI'], true, true,
E'## Task Decomposer Skill\n\n```python\n"""\nskill: task-decomposer\nversion: 1.1.0\n"""\n\ndef decompose(goal: str, max_tasks: int = 20, granularity: str = "medium") -> str:\n    """\n    Decompose a complex goal into structured subtasks.\n    :param goal: High-level goal\n    :param max_tasks: Max subtasks to generate\n    :param granularity: fine (<1h) | medium (1-4h) | coarse (1+ day)\n    :return: JSON task DAG\n    """\n    return (\n        f"Decompose this goal into a structured task DAG.\\n\\n"\n        f"Goal: {goal}\\nMax tasks: {max_tasks}\\nGranularity: {granularity}\\n\\n"\n        "Return ONLY valid JSON with this schema:\\n"\n        "{\\"goal\\":\\"string\\",\\"total_estimated_hours\\":0,\\"critical_path\\":[\\"task-id\\"],\\"tasks\\":[{\\n"\n        "  \\"id\\":\\"task-1\\",\\"title\\":\\"string\\",\\"type\\":\\"research|coding|writing|design|analysis\\",\\n"\n        "  \\"effort\\":\\"Small|Medium|Large|XL\\",\\"estimated_hours\\":0,\\n"\n        "  \\"depends_on\\":[],\\"can_parallelize_with\\":[\\"task-id\\"],\\n"\n        "  \\"acceptance_criteria\\":[\\"string\\"],\\"output_artifact\\":\\"string\\"\\n"\n        "}]}\\n\\n"\n        "Rules:\\n"\n        "- Tasks with empty depends_on can run in parallel from start\\n"\n        "- Every task must have verifiable acceptance criteria\\n"\n        "- Mark critical path (longest chain of dependencies)"\n    )\n```\n\n### Example Output\n```json\n{\n  "goal": "Build user auth system",\n  "total_estimated_hours": 16,\n  "critical_path": ["task-1", "task-3", "task-5"],\n  "tasks": [\n    {"id":"task-1","title":"Design auth flow","effort":"Small","depends_on":[],...}\n  ]\n}\n```',
'https://swarmclaw.com/skills', 'SwarmClaw', ARRAY['task-planning', 'decomposition', 'orchestration', 'dag', 'agents']),

('lobehub-skill-grammar-checker', 'skill', 'Grammar & Style Checker Skill', 'Proofreads text for grammar, punctuation, style and clarity — outputs tracked changes with explanations.',
'Comprehensive writing quality skill checking grammar, punctuation, word choice, and style. Outputs corrections in tracked-change format, explains each change, scores overall writing quality, and provides actionable style tips.',
'content-marketing', ARRAY['LobeHub', 'Open WebUI', 'Hermes Agent'], true, false,
E'## Grammar & Style Checker Skill\n\n```python\n"""\nskill: grammar-style-checker\nversion: 1.0.0\n"""\n\ndef check(text: str, mode: str = "FULL", style_guide: str = "general") -> str:\n    """\n    Check and correct grammar and style.\n    :param text: Text to check\n    :param mode: PROOFREAD | STYLE | FULL\n    :param style_guide: general | AP | Chicago | APA | Google\n    """\n    guides = {\n        "AP": "AP Style: numerals for 10+, no Oxford comma",\n        "Chicago": "Chicago Style: words for 1-99, Oxford comma required",\n        "APA": "APA Style: numbers with units always as numerals",\n        "Google": "Google Dev Style: present tense, active voice, second person"\n    }\n    guide_note = guides.get(style_guide, "")\n    return (\n        f"You are a professional editor. Check this text ({mode} mode). {guide_note}\\n\\n"\n        f"Text:\\n{text}\\n\\n"\n        "Return:\\n"\n        "## Corrected Text\\n[Full corrected version]\\n\\n"\n        "## Changes Made\\n"\n        "Each change as:\\n"\n        "- ORIGINAL: \\"original\\"\\n  CORRECTED: \\"correction\\"\\n  REASON: explanation\\n  TYPE: grammar|spelling|punctuation|style\\n\\n"\n        "## Quality Scores\\nGrammar: X/10 | Clarity: X/10 | Style: X/10 | Overall: X/10\\n\\n"\n        "## Top 3 Style Tips\\n1. [specific tip]\\n2. [tip]\\n3. [tip]"\n    )\n```',
'https://lobehub.com/plugins', 'LobeHub', ARRAY['grammar', 'writing', 'proofreading', 'style', 'editing']),

('hermes-skill-data-formatter', 'skill', 'Data Format Converter Skill', 'Converts data between JSON, CSV, YAML, TOML, XML, Markdown tables and SQL INSERT statements.',
'Swiss-army knife data transformation skill. Converts between all major structured data formats with proper type handling, nested structure support, and clean formatted output.',
'documents-data', ARRAY['Hermes Agent', 'Open WebUI', 'SwarmClaw'], true, false,
E'## Data Format Converter Skill\n\n```python\n"""\nskill: data-format-converter\nversion: 1.0.0\n"""\n\nSUPPORTED = ["json", "csv", "yaml", "toml", "xml", "markdown", "sql"]\n\ndef convert(data: str, from_format: str, to_format: str, table_name: str = "data") -> str:\n    """\n    Convert data between formats.\n    :param data: Input data as string\n    :param from_format: json|csv|yaml|toml|xml|markdown|sql\n    :param to_format: json|csv|yaml|toml|xml|markdown|sql\n    :param table_name: Table name for SQL output\n    :return: Converted data as string\n    """\n    return (\n        f"Convert the following {from_format.upper()} data to {to_format.upper()}.\\n"\n        f"Table name for SQL: {table_name}\\n\\n"\n        "Rules:\\n"\n        "- Preserve all field names exactly\\n"\n        "- Infer types: strings, numbers, booleans, null\\n"\n        "- Nested objects in CSV: flatten with dot notation (user.name)\\n"\n        "- SQL: use proper INSERT statements with type casting\\n"\n        "- Markdown tables: truncate values > 50 chars with ...\\n"\n        "Return ONLY the converted data, no explanation.\\n\\n"\n        f"Input data:\\n{data}"\n    )\n```\n\n### Supported Conversions\n- JSON <-> CSV, YAML, TOML, XML, Markdown table, SQL INSERT\n- CSV <-> JSON, YAML, Markdown table\n- Any -> Any (all 7 formats fully cross-convertible)',
'https://hermesagent.ai/skills', 'Hermes Agent', ARRAY['data', 'json', 'csv', 'yaml', 'conversion']),

('swarmclaw-skill-code-generator', 'skill', 'Code Generator Skill', 'Generates production-ready code from natural language specs — 20+ languages with tests and JSDoc.',
'High-quality code generation from natural language. Supports 20+ languages with unit tests, documentation, and language-specific best practices applied automatically.',
'documents-data', ARRAY['SwarmClaw', 'Open WebUI', 'LobeHub', 'Claude'], true, true,
E'## Code Generator Skill\n\n```python\n"""\nskill: code-generator\nversion: 2.0.0\n"""\n\nSUPPORTED_LANGUAGES = [\n    "python","typescript","javascript","go","rust","java",\n    "csharp","cpp","php","ruby","swift","kotlin","sql",\n    "bash","r","dart","scala","elixir"\n]\n\ndef generate(spec: str, language: str = "typescript", include_tests: bool = True,\n             include_docs: bool = True, style: str = "production") -> str:\n    """\n    Generate code from a natural language specification.\n    :param spec: What the code should do\n    :param language: Programming language\n    :param include_tests: Generate unit tests\n    :param include_docs: Add JSDoc/docstrings\n    :param style: production | minimal | educational\n    """\n    style_notes = {\n        "production": "Production-quality: handle all errors, validate inputs, use types.",\n        "minimal": "Simplest correct implementation. Prioritize readability.",\n        "educational": "With inline comments explaining each logical step for learners."\n    }\n    parts = [\n        f"Generate {language} code for: {spec}\\n",\n        f"Style: {style_notes.get(style, style_notes[\'production\'])}",\n    ]\n    if include_docs:\n        parts.append("Add JSDoc/docstring comments to all public functions.")\n    if include_tests:\n        parts.append("Include unit tests covering: happy path, edge cases, error cases.")\n    parts.append("Output: 1) Brief approach explanation 2) Main code 3) Tests 4) Usage example")\n    return "\\n".join(parts)\n```\n\n### Language Defaults\n- **TypeScript**: strict mode, explicit return types, Zod validation\n- **Python**: type hints, pytest fixtures, dataclasses\n- **Go**: explicit errors, table-driven tests\n- **Rust**: Result/Option types, no unwrap in production',
'https://swarmclaw.com/skills', 'SwarmClaw', ARRAY['code-generation', 'typescript', 'python', 'go', 'testing']),

('agency-skill-report-writer', 'skill', 'Business Report Writer Skill', 'Generates executive reports, status updates, project summaries and business analyses in polished prose.',
'Professional business writing skill transforming data and bullets into polished executive-level reports. Supports weekly status, post-mortems, market analyses, board updates, and investor letters.',
'business-operations', ARRAY['Agency Agents', 'Open WebUI', 'Hermes Agent'], true, false,
E'## Business Report Writer Skill\n\n```python\n"""\nskill: business-report-writer\nversion: 1.0.0\n"""\n\nREPORT_TYPES = {\n    "STATUS": "Weekly/Sprint status report",\n    "POSTMORTEM": "Project post-mortem / retrospective",\n    "MARKET": "Market analysis brief",\n    "BOARD": "Board update narrative",\n    "INVESTOR": "Investor update letter",\n    "OKR": "OKR review and scoring"\n}\n\nAUDIENCE_NOTES = {\n    "technical": "Include implementation details. Appendix for specs.",\n    "management": "Status, risks, decisions needed. No deep technical details.",\n    "executive": "Outcomes and business impact. Numbers and trends.",\n    "board": "Strategy and governance lens. Key risks. Forward-looking.",\n    "investor": "Growth, metrics, milestones, use of funds, next steps."\n}\n\ndef write_report(data: dict, report_type: str = "STATUS",\n                audience: str = "management", length: str = "medium") -> str:\n    """\n    Generate a business report.\n    :param data: Facts, metrics, context as dict\n    :param report_type: STATUS|POSTMORTEM|MARKET|BOARD|INVESTOR|OKR\n    :param audience: technical|management|executive|board|investor\n    :param length: brief (1 page)|medium (2-3 pages)|full (5+ pages)\n    """\n    audience_note = AUDIENCE_NOTES.get(audience, "")\n    return (\n        f"Write a {report_type} report for a {audience} audience ({length}).\\n"\n        f"Guidance: {audience_note}\\n\\n"\n        f"Input data: {data}\\n\\n"\n        "Format as polished markdown with:\\n"\n        "- Executive summary (3 sentences max)\\n"\n        "- Key sections for this report type\\n"\n        "- Tables for comparative data\\n"\n        "- Clear action items with owners and dates\\n"\n        "- Professional tone, no hedging language"\n    )\n```',
'https://agencyagents.ai/skills', 'Agency Agents', ARRAY['reports', 'business-writing', 'executive', 'documentation', 'analysis']);
